INSERT INTO public.products (slug, name, category, price_tzs, unit, short_description, long_description, image_key, sort_order) VALUES
('outdoor-bench-table-set-black', 'Outdoor Table & Bench Set (Black)', 'Furniture', 1450000, 'each', 'Heavy-duty recycled plastic table with two matching benches in charcoal black.', 'A complete outdoor seating set moulded from 100% recycled plastic: one slatted table plus two free-standing benches. The chunky square frames carry real weight, so the set stays put in wind and handles daily use in schools, lodges and public courtyards. Colour runs right through the material, so scratches never show bare timber.', 'furniture-bench-set-black', 9),
('picnic-table-with-benches', 'Picnic Table with Attached Benches', 'Furniture', 1150000, 'each', 'All-in-one picnic table with fixed bench seats, sand top on a charcoal frame.', 'A one-piece picnic table with benches bolted straight to the frame, so nothing wanders off and nothing wobbles. The sand coloured top sits on a charcoal base for a clean two-tone finish that suits gardens, lodges and campsites. Fully weatherproof: no rot, no termites, no annual varnishing.', 'furniture-picnic-table', 10),
('outdoor-dining-set-six-seat', 'Outdoor Dining Set, Table & 6 Chairs', 'Furniture', 2400000, 'each', 'Six-seat dining table with high-back chairs in soft off-white recycled plastic.', 'A six-seat dining set built entirely from recycled plastic lumber, with a trestle-style table and six high-back chairs. The pale off-white finish stays cool in direct sun and washes clean with water. Ideal for terraces, garden restaurants and family compounds that need furniture which lives outdoors all year.', 'furniture-dining-set', 11);